action.new:
return jsLibraries.filter((lib, index, self) =>
    index === self.findIndex(t => t.id === lib.id)
  ).map(lib => ({
    detector: /** @type {'js'} */ ('js'),
    id: lib.id,
    name: lib.name,
    version: lib.version || undefined,
    npm: lib.npm || undefined,
  }));

